class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> ans;
        for (int i = 1; i <= numRows; i++) {

            if (i == 1) {
                vector<int> arr;
                arr.push_back(1);
                ans.push_back(arr);
            } else {
                vector<int> arr(i, 0);
                int n = 1;
                for (int j = 0; j < i / 2 + 1; j++) {
                    if (j == 0) {
                        arr[j] = 1;
                        arr[i - j - 1] = 1;
                    } else {
                        n *= (i - j);
                        n /= j;
                        arr[j] = n;
                        arr[i - j - 1] = n;
                    }
                }
                ans.push_back(arr);
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> ans;
        for (int i = 1; i <= numRows; i++) {
            vector<int> arr;
            int n = 1;
            for (int j = 0; j < i; j++) {
                if (j == 0 || j == i)
                    arr.push_back(1);
                else {
                    n *= (i - j);
                    n /= j;
                    arr.push_back(n);
                }
            }
            ans.push_back(arr);
        }
        return ans;
    }
};

class Solution:
    def intToRoman(self, num: int) -> str:
        d = {1:'I', 5:'V',10:'X',50:'L',100:'C',500:'D',1000:'M', 4:'IV', 9:'IX', 40:'XL', 90:'XC', 400:'CD', 900:'CM'}
        res = ''
        gtl = sorted(list(d.keys()))
        gtl.reverse()
        # print(f'gtl: {gtl}')
        i = 0
        while num > 0:
            # print(f'res: {res} | num: {num} | current gtl: {gtl[i]}')
            if(num >= gtl[i]):
                res += d[gtl[i]]
                num -= gtl[i]
            else:
                i+=1
        return res

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int min_value = INT_MAX;
        int max_profit = 0;

        for (auto i : prices) {
            min_value = min(min_value, i);
            max_profit = max(max_profit, i - min_value);
        }
        return max_profit;
    }
};

class Solution {
public:
    bool isPalindrome(string s) {
        string ans;
        for(auto i: s){
            if(isalnum(i)) ans += tolower(i);
        }
        int l = 0;
        int r = ans.size()-1;
        while(l<r){
            if(ans[l] != ans[r]) return false;
            r--;
            l++; 
        }
        return true;
    }
};

class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        if (nums.size() < 2) {
            return nums.size();
        }
        sort(nums.begin(), nums.end());
        int count = 1;
        int ans = 1;
        for (int i = 1; i < nums.size(); i++) {
            if (nums[i] == nums[i - 1]) {
                continue;
            } else if (nums[i] == nums[i - 1] + 1) {
                count++;
            } else {
                count = 1;
            }
            ans = max(ans, count);
        }
        return ans;
    }
};

class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        if(nums.size() < 2){
            return nums.size();
        }
        sort(nums.begin() , nums.end());
        int count = 0;
        int i = 1 ;
        int ans = 0;
        while(i < nums.size()){
            if(nums[i] == nums[i-1]){
                count++;
            }else{
                ans = max(ans,count);
                count = 0;
            }
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> sequentialDigits(int low, int high) {
        vector<int> ans;

        int lowLen = to_string(low).size();
        int highLen = to_string(high).size();

        for (int len = lowLen; len <= highLen; len++) {

            // Largest starting digit possible
            for (int start = 1; start <= 10 - len; start++) {

                int num = 0;

                for (int d = 0; d < len; d++) {
                    num = num * 10 + (start + d);
                }

                if (num >= low && num <= high)
                    ans.push_back(num);
            }
        }

        return ans;
    }
};

class Solution:
    def romanToInt(self, s: str) -> int:
        roman = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000,
        }
        ans = 0
        prev = 0
        for i in reversed(s):
            value = roman[i]
            if(value < prev):
                ans -= value
            else:
                ans += value
                prev = value
        return ans

