 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */
struct ListNode* removeNthFromEnd(struct ListNode* head, int n) {
    struct ListNode *ptr1 = head, *ptr2 = head;
    for (int i = 0; i < n; i++)
        ptr2 = ptr2->next;
    if (ptr2 == NULL)
        return head->next;
    while (ptr2->next != NULL) {
        ptr1 = ptr1->next;
        ptr2 = ptr2->next;
    }
    ptr1->next = ptr1->next->next;
    return head;
}

