class Solution {
public:
    int reverseBits(int n) {
        string a = "";
        for (int i = 0; i < 32; i++) {
            a += (n % 2) + '0';
            n = n / 2;
        }
        reverse(a.begin() , a.end());
        int ans = 0;
        for (int i = 0; i < a.size(); i++) {
            if (a[i] - '0' == 1)
                ans += (a[i] - '0') * pow(2, i);
        }
        return ans;
    }
};

class Solution {
public:
    int hammingWeight(int n) {
        int count = 0;
        while (n > 0) {
            if (n % 2 == 1)
                count++;
            n = n / 2;
        }
        return count;
    }
};

