    struct ListNode *ptr1 = l1, *ptr2 = l2, *ptr3 = l3;
    int digit = 0;
    while (ptr1 != NULL && ptr2 != NULL) {
        digit = ptr1->val + ptr2->val + digit;
        ptr3 = add(ptr3, digit % 10);
        ptr1 = ptr1->next;
        ptr2 = ptr2->next;
        digit = digit / 10;
    }
    if (ptr1 != NULL) {
        digit = ptr1->val + digit;
        ptr3 = add(ptr3, digit % 10);
        ptr1 = ptr1->next;
        digit = digit / 10;
    }
    if (ptr2 != NULL) {
        digit = ptr2->val + digit;
        ptr3 = add(ptr3, digit % 10);
        ptr2 = ptr2->next;
        digit = digit / 10;
    }
    if (digit > 10) {
        ptr3 = add(ptr3, digit);
    }
    return l3;
}

