struct ListNode* mergeKLists(struct ListNode** lists, int listsSize) {
    if (listsSize == 0)
        return NULL;
    while (listsSize > 1) {
        int j = 0;
        for (int i = 0; i < listsSize; i = i + 2) {
            if (i + 1 < listsSize)
                lists[j++] = mergeTwoLists(lists[i], lists[i + 1]);
            else
                lists[j++] = lists[i];
        }
        listsSize = j;
    }
