    struct ListNode *ptr = &dummy, *prev, *last;
    for (int i = 0; i < k; i++) {
        prev = ptr;
        last = ptr->next;
        while (last->next != NULL) {
            prev = last;
            last = last->next;
        }
        last->next = dummy.next;
        dummy.next = last;
        prev->next = NULL;
    }
    return dummy.next;
}

