class Solution {
public:
    bool isValid(string s) {
        stack<char> st;
        for (auto i : s) {
            if (i == '{' || i == '[' || i == '(') {
                st.push(i);
            } else {
                if (st.empty())
                    return false;
                else {
                    char ch = st.top();
                    st.pop();
                    if ((i == ')' && ch == '(') || (i == ']' && ch == '[') ||
                        (i == '}' && ch == '{')) {
                        continue;
                    } else {
                        return false;
                    }
                }
            }
        }
        return st.empty();
    }
};

class Solution {
public:
    bool isPalindrome(string s) {
        string ans;
        for(auto i: s){
            if(isalnum(i)) ans += tolower(i);
        }
        int l = 0;
        int r = ans.size()-1;
        while(l<r){
            if(ans[l] != ans[r]) return false;
            r--;
            l++; 
        }
        return true;
    }
};

class Solution {
