class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(n);
        int left = 1, right = 1;
        for (int i = 0; i < n; i++) {
            ans[i] = left;
            left *= nums[i];
        }
        for (int i = n - 1; i > -1; i--) {
            ans[i] *= right;
            right *= nums[i];
        }
        return ans;
    }
};

