class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> ans(n, 0);
        stack<int> st;
        for (int i = n - 1; i > -1; i--) {
            while (!st.empty() && temperatures[st.top()] <= temperatures[i]) {
                st.pop();
            }
            if (!st.empty()) {
                ans[i] = st.top() - i;
            }
            st.push(i);
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> ans;

        for (int i = 0; i < n; i++) {
            int days = 0;

            for (int j = i + 1; j < n; j++) {
                if (temperatures[j] > temperatures[i]) {
                    days = j - i;
                    break;
                }
            }

            ans.push_back(days);
        }

        return ans;
    }
};

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        if (n < 2)
            return {0};
        vector<int> ans;
        for (int i = 0; i < n; i++) {
            int a = 0;
            for (int j = i + 1; j < n; j++) {
                if (temperatures[i] < temperatures[j]) {
                    ans.push_back(j-i);
                    a++;
                    break;
                }
            }
            if (a == 0)
                ans.push_back(0);
        }
        return ans;
    }
};
